import axios from "axios";
import { useloggedUserInfo } from "./stores/UserInfo";
// Our APIGATEWAY URL
const baseDomain = process.env.VUE_APP_API_URL;
const baseURL = `${baseDomain}`;
const baseCommonURL = process.env.VUE_APP_COMMON_API;
const baseURLCommon = `${baseCommonURL}`;
const baseXeroURL = process.env.VUE_APP_XERO_API;
const baseURLXero = `${baseXeroURL}`;
const baseCompanyURL = process.env.VUE_APP_COMPANY_API_URL;
const baseURLCompany = `${baseCompanyURL}`;
const instance = axios.create({
    baseURL,
});
const instanceCommon = axios.create({
    baseURL: baseURLCommon,
});
const instanceXero = axios.create({
    baseURL: baseURLXero,
});
const instanceCompany = axios.create({
    baseURL: baseURLCompany,
})
instance.interceptors.request.use(
    (config) => {
        const token = useloggedUserInfo().GetUserInfo.Token;
        if (token) {
            config.headers["Authorization"] = `Bearer ${token}`;
            // Check if data is FormData - if so, let axios set the content-type automatically
            // Otherwise set to application/json
            if (config.data instanceof FormData) {
                // Don't set content-type for FormData - axios will set it automatically with boundary
                delete config.headers["content-type"];
            } else if (config.url == '/ImportContactsPost' || config.url == '/AddProduct') {
                config.headers["content-type"] = "multipart/form-data";
            } else {
                config.headers["content-type"] = "application/json;charset=UTF-8";
            }
            config.headers['Access-Control-Allow-Origin'] = '*';
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);
instanceCommon.interceptors.request.use(
    (config) => {
        const token = useloggedUserInfo().GetUserInfo.Token;
        if (token) {
            config.headers["Authorization"] = `Bearer ${token}`;
            config.headers["content-type"] = "application/json;charset=UTF-8"
            config.headers['Access-Control-Allow-Origin'] = '*';
        }
        return config;
    },

    (error) => {
        return Promise.reject(error);
    }
);

instanceXero.interceptors.request.use(
    (config) => {
        const token = useloggedUserInfo().GetUserInfo.Token;
        if (token) {
            config.headers["Authorization"] = `Bearer ${token}`;
            config.headers["content-type"] = "application/json;charset=UTF-8"
            config.headers['Access-Control-Allow-Origin'] = '*';
        }
        return config;
    },

    (error) => {
        return Promise.reject(error);
    }
);
instanceCompany.interceptors.request.use(
    (config) => {
        const token = useloggedUserInfo().GetUserInfo.Token;
        if (token) {
            config.headers["Authorization"] = `Bearer ${token}`;
            config.headers["content-type"] = "application/json;charset=UTF-8"
            config.headers['Access-Control-Allow-Origin'] = '*';
        }
        return config;
    },

    (error) => {
        return Promise.reject(error);
    }
);
export default { instance, instanceCommon, instanceXero, instanceCompany };
