<template>
    <ol class="breadcrumb">
          <li class="breadcrumb-item">
            <em  class="fa fa-home"></em><RouterLink to="/User/Home">{{$t('Home')}}</RouterLink>
          </li>
          <template v-for="(item,itemIndex) in breadcrumbList">
            <li class="breadcrumb-item" :key="itemIndex" v-if="item.link"><RouterLink :to="item.link" >{{$t(item.name)}}</RouterLink></li>
            <li class="breadcrumb-item active" v-if="!item.link" :key="itemIndex">{{$t(item.name)}}</li>
          </template>
        </ol>
</template>

<script>
    export default{
       name: "breadcrumb",
       data: function(){
            return{
                breadcrumbList: []
            }
       },
       mounted() {
            this.updateBreadcrumb();
       },
       watch: {
           '$route':function(){
                this.updateBreadcrumb();
           }
       },
    methods: {
        updateBreadcrumb() {
            if (this.$route.meta && Array.isArray(this.$route.meta.breadcrumb)) {
                this.breadcrumbList = this.$route.meta.breadcrumb.map(item => {
                    if (item.name === ':tab') {
                        return {
                            ...item,
                            name: this.$route.params.tab,
                            isDynamic: true
                        };
                    }
                    return item;
                });
            } else {
                this.breadcrumbList = [];
            }
        }
    }
}
</script>
