Vue.filter('formatDate', function (value){
  if (value) {
    return moment(value, "YYYY-MM-DD").format(String('MM/DD/YYYY'))
}
})
Vue.filter('formatTime', function (value){
  if (value) {
    return moment(value, "HH:mm:ss").format(String('h:mm A'));
}
})
Vue.filter('formatDateTime', function (value){
  if (value) {
    return moment(value, "YYYY-MM-DD HH:mm:ss").format(String('MM/DD/YYYY h:mm A'))
}
})
Vue.filter('formatDatee', function (value) {
    if (!value) return '';
    if (value instanceof Date && !isNaN(value.getTime())) {
        return moment(value).format('MM/DD/YYYY');
    }
    const m = moment(value, ['YYYY-MM-DD', 'MM/DD/YYYY'], true);
    return m.isValid() ? m.format('MM/DD/YYYY') : '';
});
Vue.filter('formatDateForForm', function (value) {
    if (!value) return '';
    if (!(value instanceof Date) || isNaN(value.getTime())) {
        return '';
    }
    return moment(value).format('MM/DD/YYYY');
});
Vue.filter('formatDateForFormString', function (value) {
    if (!value) return '';
    return moment(value).isValid() ? moment(value).format('MM/DD/YYYY') : '';
});
Vue.filter('formatDateYYMMDD', function (value) {
  if (!value) return '';
  return moment(value).isValid()
    ? moment(value).format('YYYY-MM-DD')
    : '';
});

Vue.filter('currency', function (value){
  if (value) {
    var n = Number.parseFloat(value);
    if (!value || isNaN(n) || n < 0) return 0;
    return n.toFixed(2);
} else {
    return value;
}
})
Vue.filter('truncate', function (text, length, suffix) {
  if (text.length > length) {
      return text.substring(0, length) + suffix;
  } else {
      return text;
  }
});


