<template>
    <span class="p-actions float-md-right float-left mb-wid-100">
        <a href="javascript:;" v-on:click="backToList()" class="p-action-btn text-white d-none d-md-inline-block">
            <em aria-hidden="true" class="fa fa-angle-double-left"></em>
            <br>{{$t('Back')}}
        </a>
    </span>
</template>
<script>
    export default {
        methods: {
            backToList: function() {
                if (window.history.length > 1) {
                    this.$router.back();
                } else {
                    this.$router.push('/');
                }
            }
        },
    }
</script>